def translate_aura(source: str) -> str:
    numbers = re.findall(r"\d+(?:\.\d+)?", source)
    pattern = re.sub(r"\d+(?:\.\d+)?", "{n}", source)
    translated = TRANSLATIONS.get(pattern)
    if translated is None:
        raise ValueError(f"untranslated client aura: {source}")
    values = iter(numbers)
    result = re.sub(r"\{n\}", lambda _m: next(values), translated)
    if re.search(r"[A-Za-z]{3,}", result):
        raise ValueError(f"English text in translated client aura: {result}")
    return result
